// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadShareTechMono = makeLoadFont('ShareTechMono');

// Module-level font loading for deterministic renders
const { fontFamily: shareTechMonoFamily } = loadShareTechMono();



export type CountdownTimerProps = Record<string, any>;

const CountdownTimer: React.FC<CountdownTimerProps> = ({
  backgroundColor = "#000000",
  transparentBackground = false,
  durationInSeconds = 10,
  timerColor = "#ff0000",
  glowIntensity = 0.8,
  reflectionOpacity = 0.4,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Safely handle transparent backgrounds
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Cinematic subtle scaling effect over the duration
  const containerScale = interpolate(frame, [0, fps * durationInSeconds], [1, 1.05], {
    extrapolateRight: "clamp",
  });

  // Dynamic breathing glow to make the LED effect feel alive
  const pulse = interpolate(
    Math.sin(frame * 0.15),
    [-1, 1],
    [0.9, 1.1]
  );
  const currentGlow = glowIntensity * pulse;

  // Exact frame-perfect countdown calculations
  const remainingFrames = Math.max(0, durationInSeconds * fps - frame);
  const totalSeconds = Math.ceil(remainingFrames / fps);
  const isFinished = totalSeconds === 0;
  
  const minutesStr = String(Math.floor(totalSeconds / 60)).padStart(2, '0');
  const secondsStr = String(totalSeconds % 60).padStart(2, '0');

  // Colon blink effect syncs perfectly with the changing numbers
  const colonOpacity = isFinished ? 1 : (frame % fps < fps / 2 ? 1 : 0.1);

  const textBaseStyle: React.CSSProperties = {
    fontSize: width * 0.25,
    color: timerColor,
    fontFamily: shareTechMonoFamily,
    textAlign: "center",
    lineHeight: 1,
    fontWeight: 400,
    letterSpacing: width * 0.01,
    // Additive shadow layers to simulate a bright glowing core and soft ambient light
    textShadow: `
      0 0 ${width * 0.005 * currentGlow}px ${timerColor},
      0 0 ${width * 0.015 * currentGlow}px ${timerColor},
      0 0 ${width * 0.03 * currentGlow}px ${timerColor},
      0 0 ${width * 0.06 * currentGlow}px ${timerColor}
    `,
    fontVariantNumeric: "tabular-nums", // Prevents horizontal jitter as numbers change
    transition: "none",
  };

  const renderTimeText = () => (
    <div style={{ display: 'flex', flexDirection: 'row', alignItems: 'center', justifyContent: 'center', transition: "none" }}>
      <span>{minutesStr}</span>
      <span style={{ opacity: colonOpacity, transform: "translateY(-5%)" }}>:</span>
      <span>{secondsStr}</span>
    </div>
  );

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor }}>
      <AbsoluteFill
        style={{
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          justifyContent: "center",
          transform: `scale(${containerScale})`,
          transition: "none",
        }}
      >
        {/* Main Timer Display */}
        <div style={{ ...textBaseStyle, zIndex: 2 }}>
          {renderTimeText()}
        </div>

        {/* Mirrored Floor Reflection */}
        <div
          style={{
            ...textBaseStyle,
            transform: "scaleY(-1)",
            opacity: reflectionOpacity,
            // Mask fades out the reflection as it goes downwards visually
            WebkitMaskImage: "linear-gradient(to top, rgba(0,0,0,1) 0%, rgba(0,0,0,0) 70%)",
            maskImage: "linear-gradient(to top, rgba(0,0,0,1) 0%, rgba(0,0,0,0) 70%)",
            marginTop: -height * 0.02, // Optically tighten the gap between baseline and reflection
            zIndex: 1,
          }}
        >
          {renderTimeText()}
        </div>
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

export default CountdownTimer;